def next_departure(times, now):
    """Find the next sailing at or after a given time."""
    later = [t for t in sorted(times) if t >= now]
    if later:
        return later[0]
    return min(times) + DAY_MINUTES if times else None


def overlap(a, b):
    """Minutes two time windows share."""
    start = max(a[0], b[0])
    end = min(a[1], b[1])
    return max(0, end - start)


